package com.nextrade.common.util; public final class Validation {private Validation(){} public static <T> T notNull(T value,String name){if(value==null)throw new IllegalArgumentException(name+" is required");return value;} public static String notBlank(String value,String name){if(value==null||value.isBlank())throw new IllegalArgumentException(name+" is required");return value.trim();} public static void positive(java.math.BigDecimal v,String n){if(v==null||v.signum()<=0)throw new IllegalArgumentException(n+" must be positive");} public static void nonNegative(java.math.BigDecimal v,String n){if(v==null||v.signum()<0)throw new IllegalArgumentException(n+" must be non-negative");}}